CREATE OR REPLACE FUNCTION app.review_queue(p_site_id uuid, p_include_decided boolean, p_limit integer, p_submission_id uuid DEFAULT NULL::uuid, p_page_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(submission_id uuid, site_id uuid, site_name text, page_id uuid, page_title text, page_slug text, version_id uuid, version_revision bigint, status submission_status, request_note text, decision_note text, submitted_by uuid, submitted_by_name text, decided_by_name text, submitted_at timestamp with time zone, decided_at timestamp with time zone, page_revision bigint, current_draft_version_id uuid, published_version_id uuid, submitted_content jsonb, submitted_meta jsonb, live_content jsonb, live_meta jsonb, carries_trusted_code boolean, trusted_code_approved_by uuid, can_review boolean, can_approve boolean, comment_count integer, unresolved_comment_count integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor uuid; bounded_limit integer;
BEGIN
  actor := app.require_actor();
  bounded_limit := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);

  RETURN QUERY
  SELECT
    sub.id,
    sub.site_id,
    site.name,
    page.id,
    page.title,
    page.slug,
    submitted.id,
    submitted.revision,
    sub.status,
    sub.note,
    sub.decision_note,
    sub.submitted_by,
    COALESCE(NULLIF(author.display_name, ''), author.email),
    COALESCE(NULLIF(reviewer.display_name, ''), reviewer.email),
    sub.created_at,
    sub.decided_at,
    page.revision,
    page.draft_version_id,
    page.published_version_id,
    submitted.content,
    submitted.meta,
    live.content,
    live.meta,
    submitted.carries_trusted_code,
    submitted.trusted_code_approved_by,
    app.can_publish_page(sub.item_id),
    app.can_publish_page(sub.item_id) AND (
      NOT submitted.carries_trusted_code
      OR submitted.trusted_code_approved_by IS NOT NULL
      OR app.is_super_admin()
    ),
    COALESCE(discussion.total, 0)::integer,
    COALESCE(discussion.unresolved, 0)::integer
  FROM public.submissions sub
  JOIN public.sites site ON site.id = sub.site_id
  JOIN public.pages page
    ON page.id = sub.item_id AND page.site_id = sub.site_id
  JOIN public.page_versions submitted
    ON submitted.id = sub.version_id
   AND submitted.page_id = page.id
   AND submitted.site_id = sub.site_id
  JOIN public.app_users author ON author.id = sub.submitted_by
  LEFT JOIN public.app_users reviewer ON reviewer.id = sub.decided_by
  LEFT JOIN public.page_versions live ON live.id = page.published_version_id
  LEFT JOIN LATERAL (
    SELECT count(*) AS total,
           count(*) FILTER (WHERE c.resolved_at IS NULL) AS unresolved
      FROM public.comments c
     WHERE c.site_id = sub.site_id
       AND c.item_type = 'page'
       AND c.item_id = page.id
       AND c.version_id = sub.version_id
  ) discussion ON true
  WHERE sub.item_type = 'page'
    AND app.has_page_access(sub.item_id)
    AND (sub.submitted_by = actor OR app.can_publish_page(sub.item_id))
    AND (p_site_id IS NULL OR sub.site_id = p_site_id)
    AND (p_submission_id IS NULL OR sub.id = p_submission_id)
    AND (p_page_id IS NULL OR sub.item_id = p_page_id)
    AND (COALESCE(p_include_decided, false) OR sub.status = 'open')
  ORDER BY (sub.status = 'open') DESC, sub.created_at DESC
  LIMIT bounded_limit;
END
